// Terraria (2026-10-02): its settings are launch args + a TShock config.json, not `-e` env, so
// applyGameConfigEnv cannot express them — bake them in so a fresh install / reinstall starts configured.
const scriptWithTerraria = (() => {
  if (server.osTemplate.family !== "terraria" || !server.gameConfig) return scriptWithEnv;
  const v = validateConfig("terraria", server.gameConfig as Record<string, unknown>);
  return v.ok ? applyTerrariaSetup(scriptWithEnv, v.values) : scriptWithEnv;
})();
// Family setup pipeline (integration, 2026-10-02): every family applier that has to bake settings into the
// setup script (because they are launch args / seeded files / composed env, not plain `-e` placeholders) is a
// pure rewrite applied here, each EXACTLY ONCE, in this order. Each step is a no-op for other families.
const scriptWithFamilySetup = (() => {
  const fam = server.osTemplate.family;
  let script = scriptWithTerraria;
  // survival families (vrising/enshrouded/icarus/sunkenland/nightingale): missing env baked in. Runs for every
  // family (it no-ops for others) and with a null gameConfig exactly as it did before the merge.
  script = applySurvivalSetup(script, server.osTemplate.family, server.gameConfig);
  // ark/arkasa/conan/soulmask/theisle/dragonwilds (cfg-unreal): env with no catalog placeholder, composed flags,
  // the map/mode variant and The Isle's Game.ini. Like the survival step it runs unconditionally (no-op for other families).
  script = applyUnrealSetupFor(script, server.osTemplate.family, server.gameConfig, server.gameVariant ?? null);
  if (!fam || !server.gameConfig) return script;
  // sandstorm: map/password/max players are ONE composed LAUNCH_SERVER_ENV — bake it so a fresh install / reinstall starts configured.
  if (fam === "sandstorm") {
    const v = validateConfig("sandstorm", server.gameConfig as Record<string, unknown>);
    if (v.ok) script = applySandstormSetup(script, v.values);
  }
  // Mordhau + Squad ("sim" appliers): Mordhau's ini files are seeded before first boot, Squad's MODS env is added
  // (its SERVER_NAME/FIXEDMAXPLAYERS are already `-e` placeholders).
  if (fam === "mordhau" || fam === "squad") {
    const v = validateConfig(fam, server.gameConfig as Record<string, unknown>);
    if (v.ok) script = fam === "mordhau" ? applyMordhauSetup(script, v.values) : applySquadSetup(script, v.values);
  }
  return script;
})();
// Minecraft server-software mirror (lib/mcjars/pin.ts): stage the exact jar on
// the guest and run it pinned, so container restarts never contact upstream
// (2026-10-01 PaperMC outage). A pinned LATEST resolves to the concrete
// version, and the Java image follows THAT version.
const pin = server.osTemplate.family === "minecraft" ? server.__mcJarPin ?? null : null;
const scriptWithPin = pin ? applyPinToSetupScript(scriptWithFamilySetup, pin, server.gameVariant ?? "vanilla") : scriptWithFamilySetup;
const scriptWithJavaImageRaw = applyMinecraftJavaImage(
  scriptWithPin,
  server.osTemplate.family,
  pin

