import { APPLIER_SPECS } from "../../lib/game-config-appliers";
import type { GameConfigApplier } from "./types";
import { terrariaApplier } from "./terraria";
import { dayzApplier } from "./dayz";
import { armareforgerApplier } from "./armareforger";
import { sandstormApplier } from "./sandstorm";
import { ets2Applier } from "./ets2";
import { atsApplier } from "./ats";
import { ecoApplier } from "./eco";
import { empyrionApplier } from "./empyrion";
import { spaceengineersApplier } from "./spaceengineers";
import { vintagestoryApplier } from "./vintagestory";
import { mordhauApplier } from "./mordhau";
import { squadApplier } from "./squad";
import { sdtdApplier, vrisingApplier, enshroudedApplier, icarusApplier, sunkenlandApplier, nightingaleApplier } from "./survival";

/**
 * THE applier registry. To add a family: write worker/game-config-appliers/<family>.ts
 * (+ lib/game-applier-specs/<family>.ts), then add ONE line to `register` below and
 * ONE line to APPLIER_SPECS in lib/game-config-appliers.ts. If the two disagree the
 * worker refuses to boot (and test/game-config-appliers.test.ts fails) — see `assertConsistent`.
 * worker/game-config.ts `applyRealConfig` dispatches here for every family it has no
 * inline applier for.
 */
const REGISTRY = new Map<string, GameConfigApplier>();
function register(a: GameConfigApplier) {
  REGISTRY.set(a.spec.family, a);
}

register(terrariaApplier);
register(dayzApplier);
register(armareforgerApplier);
register(sandstormApplier);
register(ets2Applier);
register(atsApplier);
register(ecoApplier);
register(empyrionApplier);
register(spaceengineersApplier);
register(vintagestoryApplier);
register(mordhauApplier);
register(squadApplier);
register(sdtdApplier);
register(vrisingApplier);
register(enshroudedApplier);
register(icarusApplier);
register(sunkenlandApplier);
register(nightingaleApplier);

/** The registered spec must be the exact object the UI derives from. */
export function assertConsistent(): void {
  for (const [family, a] of REGISTRY) {
    if (APPLIER_SPECS[family] !== a.spec) throw new Error(`game config applier "${family}": its spec is not the one listed in lib/game-config-appliers.ts APPLIER_SPECS`);
  }
  for (const family of Object.keys(APPLIER_SPECS)) {
    if (!REGISTRY.has(family)) throw new Error(`game config applier "${family}" is in APPLIER_SPECS but not registered in worker/game-config-appliers/index.ts`);
  }
}
assertConsistent();

export function getApplier(family: string): GameConfigApplier | null {
  return REGISTRY.get(family) ?? null;
}
export function registeredFamilies(): string[] {
  return [...REGISTRY.keys()];
}

