import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";

/**
 * The runner every applier goes through. It owns the boring, easy-to-get-wrong
 * parts so an applier only contains its own mechanism:
 *   - which fields are in play (handled ∩ changed) and the "saved but not applied" note for the rest
 *   - idempotent no-op when none of the changed fields belong to the applier
 *   - secret redaction of every note (values of spec fields flagged `secret`, plus any
 *     extra strings an applier registers)
 *   - never throws: an exception becomes an honest failed outcome
 */
export type RunBase = Omit<ApplierContext, "touched" | "family"> & { family?: string };

export function redactor(secrets: string[]): (s: string) => string {
  const list = secrets.filter((s) => s.length >= 3);
  return (s) => list.reduce((acc, x) => acc.split(x).join("***"), s);
}

export function secretValues(applier: GameConfigApplier, values: Record<string, unknown>): string[] {
  return Object.entries(applier.spec.fields)
    .filter(([, f]) => f.secret)
    .map(([k]) => String(values[k] ?? ""))
    .filter((v) => v.length > 0);
}

export async function runApplier(applier: GameConfigApplier, base: RunBase): Promise<ApplyOutcome> {
  const { spec } = applier;
  const handled = Object.keys(spec.fields);
  const keepVariant = spec.handlesVariant === true;
  const changed = base.changed?.filter((k) => !k.startsWith("_") && (k !== "variant" || keepVariant));
  const touched = changed ? [...handled.filter((k) => changed.includes(k)), ...(keepVariant && changed.includes("variant") ? ["variant"] : [])] : handled;
  const redact = redactor(secretValues(applier, base.values));

  const unhandled = changed ? changed.filter((k) => !(k in spec.fields) && k !== "variant") : [];
  const tail = unhandled.length
    ? [`Saved but not applied to the running game: ${unhandled.join(", ")}. We can't push ${unhandled.length === 1 ? "that setting" : "those settings"} to the server yet.`]
    : [];

  if (touched.length === 0) {
    return { ok: true, applied: [], notes: ["Nothing in this change needs to be applied to the running server.", ...tail] };
  }
  // The worker hands over `{}` when the saved settings no longer pass validation. Appliers read
  // `values[...]`, so an empty map would write BLANKS (name, password...) over the live config.
  if (Object.keys(base.values).length === 0) {
    return { ok: false, applied: [], notes: ["The saved settings didn't pass validation, so nothing was changed on your server. Open Settings, fix the highlighted field and save again.", ...tail] };
  }
  try {
    const out = await applier.apply({ ...base, family: base.family ?? spec.family, touched });
    return { ...out, applied: out.applied.map(redact), notes: [...out.notes.map(redact), ...tail] };
  } catch (e) {
    return { ok: false, applied: [], notes: [redact(`Apply failed: ${(e as Error).message}`.slice(0, 300)), ...tail] };
  }
}

