/**
 * Game config appliers — the CLIENT-SAFE half (pure data, no I/O, no node imports).
 *
 * Every family that can really push its Settings page into the running game has
 * ONE spec here (the declaration of which schema fields it handles and how each
 * takes effect) and ONE applier in worker/game-config-appliers/<family>.ts (the
 * code that does it). The settings page, `canApplyConfig`, `LIVE_APPLY_FIELDS` and
 * `fieldAppliesLive` (lib/game-config.ts) are all DERIVED from `APPLIER_SPECS`,
 * and the worker's registry reads the very same spec object, so what the page
 * promises and what the worker does cannot drift. Guide: docs/DOCUMENTATION.md,
 * "Game config appliers".
 */

/**
 * How one schema field reaches the running game:
 *  - "live"     applied on save, no restart (rcon / live command)
 *  - "recreate" applied on save by rebuilding the container (a brief restart is part of the apply)
 *  - "restart"  written on save, in effect after the server restarts ("Apply & restart")
 * A schema field that is NOT listed in a spec is "saved only" and the page says so.
 */
export type FieldWhen = "live" | "recreate" | "restart";

export type FieldApply = {
  when: FieldWhen;
  /** Shown under the field. Use it for honest caveats (e.g. "creates a new world; your current world is kept"). */
  note?: string;
  /** The value is a credential: it is redacted from every note/log the framework produces. */
  secret?: boolean;
};

