export async function applyRealConfig(
  server: SshServer,
  family: string,
  values: Values,
  opts?: { changed?: string[]; restart?: boolean },
): Promise<ApplyOutcome> {
  return withSsh(server, async (conn, sftp) => {
    switch (family) {
      case "minecraft":
        return applyMinecraft(conn, sftp, values, server);
      case "rust":
        return applyRust(conn, sftp, values, server.gameVariant ?? "vanilla");
      case "valheim":
        return applyValheim(conn, sftp, values, server.gameVariant ?? "vanilla");
      case "palworld":
        return applyPalworld(conn, sftp, values);
      case "bedrock":
        return applyBedrock(conn, sftp, values);
      // dayz: now an applier (worker/game-config-appliers/dayz.ts); the old inline applyDayZ is gone.
      case "fivem":
        // Feature-flagged family (lib/fivem.ts). File-based cfg renderer —
        // NOT in REAL_APPLY_FAMILIES until live-verified, same rule as dayz.
        return applyFivem(conn, server.id, values);
      default: {
        // Applier registry (worker/game-config-appliers/index.ts): one file per family.
        const applier = getApplier(family);
        if (!applier) return { ok: false, applied: [], notes: [`No real apply implemented for "${family}".`] };
        return runApplier(applier, {
          server: { id: server.id },
          values,
          changed: opts?.changed,
          restartRequested: opts?.restart === true,
          variant: server.gameVariant ?? null,
          guest: {
            exec: (cmd, timeoutMs) => execRemote(conn, cmd, timeoutMs),
            readFile: (path) => sftpRead(sftp, path),
            writeFile: (path, content) => sftpWrite(sftp, path, content),
          },
          unit: await resolveGameUnit(conn, family),
          waitPort: () =>
            waitForGamePort(server as unknown as ControlServer, Math.max(60_000, controlSpec(family) ? startWindowMs(controlSpec(family)!) : 0), 5_000),
        });

/**
 * Families whose settings the worker can actually WRITE to the game server.
 *
 * worker/game-config.ts throws a customer-facing "your settings are NOT in
 * effect" for anything outside this set unless ENABLE_REAL_GAMECFG is on — so
 * for the other 39 families the UI was accepting a save, saying "queued for
 * apply", and the job then failing. The set lives here so the page can TELL the
 * customer before they type, instead of after the job fails; the worker imports
 * the same constant, so the two cannot drift.
 */
// `dayz` is in here via APPLIER_SPECS (applier built 2026-10-02) but has NOT been confirmed against a
// running container: no Steam account exists in this environment to boot one (lib/dayz-steam.ts).
export const REAL_APPLY_FAMILIES = new Set<string>([
  "palworld", "minecraft", "rust", "valheim", "bedrock", "projectzomboid",
  // Every family with an applier (lib/game-config-appliers.ts APPLIER_SPECS) — derived, never listed twice.
  ...(appliersEnabled() ? Object.keys(APPLIER_SPECS) : []),
]);

/**
 * Families where only SOME fields reach the running game. A family listed here
 * is in REAL_APPLY_FAMILIES (so the job runs) but every field NOT in its set is
 * saved only; the settings page says so per field. Families absent from this
 * map apply every field.
 *
 * projectzomboid (2026-10-02): everything except ADMIN_USERNAME, via its applier spec
 * (lib/game-applier-specs/projectzomboid.ts); ADMIN_USERNAME is the already-created account
 * and is not renamed on a running server.
 */
export const LIVE_APPLY_FIELDS: Record<string, ReadonlySet<string>> = {
  // Applier families (lib/game-config-appliers.ts): exactly the fields the applier's spec declares, so the
  // page's per-field "applies on save / needs restart / saved only" cannot drift from what the worker does.
  ...(appliersEnabled() ? Object.fromEntries(Object.entries(APPLIER_SPECS).map(([f, s]) => [f, new Set(Object.keys(s.fields))])) : {}),
};

/** How a field reaches the game for an applier family ("live" | "recreate" | "restart"), else null (saved only / no applier). */
export function fieldApplyInfo(family: string | null | undefined, key: string): FieldApply | null {
  return applierFieldApply(family, key);
}

/** Whether changing `key` really reaches the running game server. */
export function fieldAppliesLive(family: string | null | undefined, key: string): boolean {
  if (!family) return false;
  const only = LIVE_APPLY_FIELDS[family];
  return only ? only.has(key) : canApplyConfig(family);
}

/** Whether a family's saved settings will really reach the game server. */
export function canApplyConfig(family: string | null | undefined): boolean {
  return !!family && (process.env.ENABLE_REAL_GAMECFG === "1" || REAL_APPLY_FAMILIES.has(family));
}

export function familyFor(server: ServerLike | null | undefined): string | null {
  if (!server) return null;
  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  if (fam && GAME_CONFIG_SCHEMAS[fam]) return fam;
  return null;
}

/** The customization schema for a family, or null. */

